    'service.promise.title': 'Unser Qualitätsversprechen',
    'service.promise.subtitle': 'Darauf können Sie sich verlassen',
    'service.promise.1.title': 'Schnell & Unkompliziert',
    'service.promise.1.desc': 'Von der ersten Anfrage bis zur Fahrzeugübergabe – wir machen den Prozess so einfach und schnell wie möglich. Keine unnötige Bürokratie, keine versteckten Kosten.',
    'service.promise.2.title': 'Sicher & Transparent',
    'service.promise.2.desc': 'Alle Fahrzeuge sind geprüft und dokumentiert. Sie erhalten vollständige Transparenz über Zustand, Historie und Ausstattung. Keine bösen Überraschungen.',
    'service.promise.3.title': 'Persönlich & Kompetent',
    'service.promise.3.desc': 'Unser erfahrenes Team steht Ihnen mit Rat und Tat zur Seite. Individuelle Beratung, die auf Ihre Bedürfnisse zugeschnitten ist.',
    'service.promise.4.title': 'Erfahren & Vertrauenswürdig',
    'service.promise.4.desc': 'Seit vielen Jahren sind wir Ihr Partner für Premium-Fahrzeuge. Viele zufriedene Kunden sprechen für unsere Qualität und Zuverlässigkeit.',

