    'legal.privacy.title': 'Datenschutzerklärung',

    // Geschichte / Story page
    'story.hero.badge': 'Seit 2014',
    'story.hero.title.prefix': 'Unsere',
    'story.hero.title.highlight': 'Geschichte',
    'story.hero.subtitle': 'Seit der Gründung am 18.07.2014 von Yves Seidler und Dimitri hat sich Nordhessen Automobile stetig weiterentwickelt – vom europaweiten Handel mit Gebrauchtfahrzeugen hin zu einem modernen Autohaus mit eigener Werkstatt und umfassendem Serviceangebot.',
    'story.vision.title': 'Unsere Vision',
    'story.vision.desc': 'Wir möchten Menschen, Fahrzeuge und Service auf höchstem Niveau miteinander verbinden. Unser Ziel ist es, europaweit als zuverlässiger Ansprechpartner für hochwertige Fahrzeuge, moderne Werkstattleistungen und persönliche Betreuung bekannt zu sein. Dabei stehen Vertrauen, Qualität und langfristige Kundenbeziehungen im Mittelpunkt unseres Handelns.',
    'story.mission.title': 'Unsere Mission',
    'story.mission.desc': 'Wir bieten unseren Kunden ein umfassendes Mobilitätskonzept – vom Fahrzeugkauf über Finanzierung und Fahrzeugexport bis hin zu professionellen Werkstatt- und Serviceleistungen. Mit Leidenschaft für Automobile, modernen Arbeitsprozessen und einem starken Team schaffen wir Lösungen, die individuell, transparent und zuverlässig sind. Unser Anspruch ist es, jeden Kunden so zu betreuen, wie wir selbst betreut werden möchten.',
    'story.timeline.badge': 'Historie',
    'story.timeline.title': 'Unsere Meilensteine',
    'story.timeline.2014.title': 'Der Start',
    'story.timeline.2014.desc': 'Gründung am 18.07.2014 – Beginn des europaweiten Verkaufs von Gebrauchtfahrzeugen. Vertrauen, Qualität und Kundenzufriedenheit bilden seitdem die Grundlage unseres Unternehmens.',
    'story.timeline.2015.title': 'Eigene Werkstatt',
    'story.timeline.2015.desc': 'Gründung der eigenen Werkstatt für interne Fahrzeugreparaturen und Aufbereitungen zur Sicherstellung hoher Qualitätsstandards.',
    'story.timeline.2016.title': 'Wachstum & Logistik',
    'story.timeline.2016.desc': 'Erweiterung des Teams in Fahrzeugdisposition und Fahrzeuglogistik für professionelle Abläufe.',
    'story.timeline.2019_20.title': 'Team-Erweiterung',
    'story.timeline.2019_20.desc': 'Ausbau der Bereiche Fuhrparkmanagement, Verkauf und Buchhaltung.',
    'story.timeline.2021.title': 'Ausbildung & Zukunft',
    'story.timeline.2021.desc': 'Einstellung des ersten Auszubildenden zum Automobilkaufmann – ein wichtiger Schritt in Richtung Nachwuchsförderung.',
    'story.timeline.2023.title': 'Ausbau Sandershäuser Straße',
    'story.timeline.2023.desc': 'Erweiterung um ein weiteres Gebäude in der Sandershäuser Straße 89 mit zusätzlichen Büro-, Innen- und Außenstellflächen.',
    'story.timeline.2024.title': 'Neue moderne Werkstatt',
    'story.timeline.2024.desc': 'Umzug in eine rund 700 qm große Werkstatt mit fünf vollständig ausgestatteten Arbeitsplätzen.',
    'story.timeline.2025.title': 'Verstärkung im Verkauf',
    'story.timeline.2025.desc': 'Erweiterung des Verkaufsteams um weitere Mitarbeiter aufgrund der hohen Nachfrage.',
    'story.timeline.2026.title': 'Nordhessen Service GmbH',
    'story.timeline.2026.desc': 'Gründung der Nordhessen Service GmbH als KFZ-Reparatur-Meisterbetrieb für Privat- und Gewerbekunden.',
    'story.values.badge': 'Unsere Werte',
    'story.values.title': 'Wofür wir stehen',
    'story.values.trust.title': 'Vertrauen & Transparenz',
    'story.values.trust.desc': 'Wir beraten ehrlich, fair und nachvollziehbar. Unsere Kunden sollen sich bei jedem Schritt sicher und gut aufgehoben fühlen.',
    'story.values.service.title': 'Serviceorientierung',
    'story.values.service.desc': 'Kundenzufriedenheit steht für uns an erster Stelle. Wir bieten individuelle Lösungen und begleiten unsere Kunden langfristig.',
    'story.values.quality.title': 'Qualität & Zuverlässigkeit',
    'story.values.quality.desc': 'Erstklassiger Fahrzeugverkauf, professioneller Werkstattservice und ein umfassender 360-Grad-Service für Ihre Mobilität.',
    'story.values.passion.title': 'Leidenschaft für Automobile',
    'story.values.passion.desc': 'Autos sind für uns mehr als nur Fahrzeuge – sie stehen für Mobilität, Emotion und Vertrauen.',
    'story.values.assurance.title': 'Qualitätssicherung',
    'story.values.assurance.desc': 'Jedes Fahrzeug wird sorgfältig Werkstatt-geprüft und professionell aufbereitet, bevor es unseren Kunden übergeben wird.',
    'story.values.team.title': 'Teamgeist',
    'story.values.team.desc': 'Unser Erfolg basiert auf einem starken und motivierten Team, das gemeinsam wächst und sich gegenseitig unterstützt.',
    'story.today.title.prefix': 'Nordhessen Automobile',
    'story.today.title.highlight': 'heute',
    'story.today.desc': 'Heute steht Nordhessen Automobile für hochwertige Gebrauchtwagen, professionelle Werkstatt- und Serviceleistungen, europaweiten Fahrzeughandel sowie persönlichen Kundenservice. Als modernes Autohaus und KFZ-Servicebetrieb in Kassel und Nordhessen entwickeln wir uns kontinuierlich weiter – immer mit dem Ziel, unseren Kunden den bestmöglichen Service rund ums Automobil zu bieten.',
    'story.today.tag.1': 'Hochwertige Gebrauchtwagen',
    'story.today.tag.2': 'Professionelle KFZ-Werkstatt',
    'story.today.tag.3': 'Europaweiter Fahrzeughandel',
    'story.today.tag.4': 'Persönlicher Kundenservice',
    'story.today.tag.5': 'Moderne Fahrzeuglogistik',
    'story.today.tag.6': 'Qualität & Vertrauen',
