    'story.cta.title.highlight': 'Traumauto?',
    'story.cta.subtitle': 'Entdecken Sie unsere aktuelle Fahrzeugauswahl oder kontaktieren Sie uns für eine persönliche Beratung.',
    'story.cta.browse': 'Fahrzeuge entdecken',
    'story.cta.contact': 'Kontakt aufnehmen',
