    'service.promise.title': 'Our Quality Promise',
    'service.promise.subtitle': 'You can rely on that',
    'service.promise.1.title': 'Fast & Uncomplicated',
    'service.promise.1.desc': 'From the first inquiry to the vehicle handover – we make the process as easy and fast as possible. No unnecessary bureaucracy, no hidden costs.',
    'service.promise.2.title': 'Secure & Transparent',
    'service.promise.2.desc': 'All vehicles are tested and documented. You receive full transparency about condition, history, and features. No bad surprises.',
    'service.promise.3.title': 'Personal & Competent',
    'service.promise.3.desc': 'Our experienced team is at your side with advice and action. Individual consultation tailored to your needs.',
    'service.promise.4.title': 'Experienced & Trustworthy',
    'service.promise.4.desc': 'For many years we have been your partner for premium vehicles. Many satisfied customers speak for our quality and reliability.',

    'service.testimonials.title': 'What Our Customers Say',
