    'service.promise.title': 'A nossa Promessa de Qualidade',
    'service.promise.subtitle': 'Pode contar com isso',
    'service.promise.1.title': 'Rápido e Descomplicado',
    'service.promise.1.desc': 'Desde a primeira consulta até à entrega do veículo – tornamos o processo o mais fácil e rápido possível. Sem burocracia desnecessária, sem custos ocultos.',
    'service.promise.2.title': 'Seguro e Transparente',
    'service.promise.2.desc': 'Todos os veículos são testados e documentados. Recebe transparência total sobre o estado, histórico e equipamento. Sem más surpresas.',
    'service.promise.3.title': 'Pessoal e Competente',
    'service.promise.3.desc': 'A nossa equipa experiente está ao seu lado com conselhos e ação. Consultoria individual adaptada às suas necessidades.',
    'service.promise.4.title': 'Experiente e Confiável',
    'service.promise.4.desc': 'Há mais de 15 anos que somos o seu parceiro em veículos premium. Milhares de clientes satisfeitos falam pela nossa qualidade e fiabilidade.',

    'service.testimonials.title': 'O que dizem os nossos clientes',
