    'service.promise.1.title': 'Rapide & Simple',
    'service.promise.1.desc': 'De la première demande à la remise du véhicule – nous rendons le processus aussi simple et rapide que possible. Pas de bureaucratie inutile.',
    'service.promise.2.title': 'Sûr & Transparent',
    'service.promise.2.desc': 'Tous les véhicules sont testés et documentés. Vous bénéficiez d\'une transparence totale sur l\'état, l\'historique et l\'équipement.',
    'service.promise.3.title': 'Personnel & Compétent',
