    // Geschichte / Story page
    'story.hero.badge': 'Depuis 2014',
    'story.hero.title.prefix': 'Notre',
    'story.hero.title.highlight': 'Histoire',
    'story.hero.subtitle': 'Depuis sa création le 18.07.2014 par Yves Seidler et Dimitri, Nordhessen Automobile n\'a cessé d\'évoluer – du commerce de véhicules d\'occasion à l\'échelle européenne à un concessionnaire moderne avec son propre atelier et une offre de services complète.',
    'story.vision.title': 'Notre Vision',
    'story.vision.desc': 'Nous voulons relier les personnes, les véhicules et le service au plus haut niveau. Notre objectif est d\'être reconnus dans toute l\'Europe comme un partenaire fiable pour les véhicules de qualité, les services d\'atelier modernes et un accompagnement personnalisé. La confiance, la qualité et les relations clients durables sont au cœur de notre activité.',
    'story.mission.title': 'Notre Mission',
    'story.mission.desc': 'Nous proposons à nos clients un concept de mobilité global – de l\'achat du véhicule au financement et à l\'export, jusqu\'aux prestations professionnelles d\'atelier et de service. Avec passion pour l\'automobile, des processus modernes et une équipe solide, nous créons des solutions personnalisées, transparentes et fiables. Notre ambition est de prendre soin de chaque client comme nous aimerions l\'être nous-mêmes.',
    'story.timeline.badge': 'Historique',
    'story.timeline.title': 'Nos Étapes Clés',
    'story.timeline.2014.title': 'Le Début',
    'story.timeline.2014.desc': 'Création le 18.07.2014 – début de notre activité de vente de véhicules d\'occasion à l\'échelle européenne. Confiance, qualité et satisfaction client sont depuis lors les fondations de notre entreprise.',
    'story.timeline.2015.title': 'Atelier interne',
    'story.timeline.2015.desc': 'Création de notre propre atelier pour les réparations et la préparation des véhicules en interne, afin de garantir un haut niveau de qualité.',
    'story.timeline.2016.title': 'Croissance et Logistique',
    'story.timeline.2016.desc': 'Renforcement de l\'équipe dans la gestion et la logistique des véhicules pour assurer des processus professionnels.',
    'story.timeline.2019_20.title': 'Renforcement de l\'équipe',
    'story.timeline.2019_20.desc': 'Développement des départements gestion de flotte, vente et comptabilité.',
    'story.timeline.2021.title': 'Formation et Avenir',
    'story.timeline.2021.desc': 'Embauche de notre premier apprenti vendeur automobile – un pas important vers la formation de la relève.',
    'story.timeline.2023.title': 'Extension Sandershäuser Straße',
    'story.timeline.2023.desc': 'Extension avec un nouveau bâtiment au Sandershäuser Straße 89, offrant des bureaux supplémentaires ainsi que des surfaces d\'exposition intérieures et extérieures.',
    'story.timeline.2024.title': 'Nouvel atelier moderne',
    'story.timeline.2024.desc': 'Emménagement dans un atelier d\'environ 700 m² avec cinq postes de travail entièrement équipés.',
    'story.timeline.2025.title': 'Renforcement des ventes',
    'story.timeline.2025.desc': 'Renforcement de l\'équipe commerciale avec de nouveaux collaborateurs pour répondre à la forte demande.',
    'story.timeline.2026.title': 'Nordhessen Service GmbH',
    'story.timeline.2026.desc': 'Création de la Nordhessen Service GmbH en tant qu\'atelier maître de réparation automobile pour les clients particuliers et professionnels.',
    'story.values.badge': 'Nos Valeurs',
    'story.values.title': 'Ce qui nous représente',
    'story.values.trust.title': 'Confiance & Transparence',
    'story.values.trust.desc': 'Nous conseillons honnêtement, équitablement et clairement. Nos clients doivent se sentir en confiance et bien accompagnés à chaque étape.',
    'story.values.service.title': 'Sens du Service',
    'story.values.service.desc': 'La satisfaction client est notre priorité. Nous proposons des solutions personnalisées et accompagnons nos clients sur le long terme.',
    'story.values.quality.title': 'Qualité & Fiabilité',
    'story.values.quality.desc': 'Vente de véhicules haut de gamme, service d\'atelier professionnel et un service complet à 360 degrés pour votre mobilité.',
    'story.values.passion.title': 'Passion pour l\'Automobile',
    'story.values.passion.desc': 'Pour nous, les voitures sont bien plus que de simples véhicules – elles incarnent mobilité, émotion et confiance.',
    'story.values.assurance.title': 'Assurance Qualité',
    'story.values.assurance.desc': 'Chaque véhicule est soigneusement contrôlé en atelier et préparé professionnellement avant d\'être remis à nos clients.',
    'story.values.team.title': 'Esprit d\'équipe',
    'story.values.team.desc': 'Notre réussite repose sur une équipe forte et motivée qui grandit ensemble et se soutient mutuellement.',
    'story.today.title.prefix': 'Nordhessen Automobile',
    'story.today.title.highlight': 'aujourd\'hui',
    'story.today.desc': 'Aujourd\'hui, Nordhessen Automobile représente des véhicules d\'occasion haut de gamme, des prestations professionnelles d\'atelier et de service, le commerce automobile à l\'échelle européenne et un service client personnalisé. En tant que concessionnaire moderne et atelier automobile à Kassel et en Hesse du Nord, nous évoluons en permanence – toujours avec l\'objectif d\'offrir à nos clients le meilleur service possible autour de l\'automobile.',
    'story.today.tag.1': 'Véhicules d\'occasion haut de gamme',
    'story.today.tag.2': 'Atelier automobile professionnel',
    'story.today.tag.3': 'Commerce automobile européen',
    'story.today.tag.4': 'Service client personnalisé',
    'story.today.tag.5': 'Logistique automobile moderne',
    'story.today.tag.6': 'Qualité & Confiance',
    'story.cta.title.prefix': 'Prêt pour votre',
    'story.cta.title.highlight': 'voiture de rêve ?',
    'story.cta.subtitle': 'Découvrez notre sélection actuelle de véhicules ou contactez-nous pour un conseil personnalisé.',
    'story.cta.browse': 'Découvrir les véhicules',
    'story.cta.contact': 'Nous contacter',
