    'faq.fin.q3.a': 'Normalmente recibirá respuesta en 24 horas. Con buena solvencia, la aprobación puede ser inmediata.',
    'faq.fin.q4.t': '¿Es obligatoria la entrada?',
    'faq.fin.q4.a': 'No es obligatoria pero sí recomendable (10-20%). Reduce la cuota mensual y los gastos totales.',
    'faq.fin.q5.t': '¿Puedo amortizar el préstamo anticipadamente?',
    'faq.fin.q5.a': 'Sí, es posible en cualquier momento. Puede haber una comisión por cancelación según contrato.',

    // Trade-in
    'faq.tr.q1.t': '¿Aceptan mi coche viejo como parte del pago?',
    'faq.tr.q1.a': 'Sí, valoramos su vehículo de forma justa y transparente según el valor actual del mercado.',
    'faq.tr.q2.t': '¿Cómo se determina el valor de mi coche?',
    'faq.tr.q2.a': 'Depende de la marca, modelo, año, kilometraje, estado y equipamiento. Usamos herramientas profesionales.',
    'faq.tr.q3.t': '¿Tengo que venderles mi coche para comprarles uno?',
    'faq.tr.q3.a': 'No, la tasación es opcional. Puede comprar su coche nuevo sin entregar el antiguo.',
    'faq.tr.q4.t': '¿Cuánto tiempo es válida la oferta de compra?',
    'faq.tr.q4.a': 'Normalmente 7 días. Los valores de mercado cambian, por lo que nos reservamos el derecho a ajustarla.',

    // Warranty
    'faq.wa.q1.t': '¿Ofrecen garantía en los vehículos?',
    'faq.wa.q1.a': 'Sí, todos nuestros coches se venden con garantía. La duración varía según el vehículo.',
    'faq.wa.q2.t': '¿Qué cubre la garantía?',
    'faq.wa.q2.a': 'Cubre normalmente motor, caja de cambios y componentes mecánicos. Se excluyen piezas de desgaste.',
    'faq.wa.q3.t': '¿Puedo ampliar la garantía?',
    'faq.wa.q3.a': 'Sí, ofrecemos varias opciones de ampliación (duración o cobertura).',
    'faq.wa.q4.t': '¿Qué ocurre en caso de avería en garantía?',
    'faq.wa.q4.a': 'Contacte con nosotros de inmediato. Coordinaremos la reparación con nuestros talleres asociados.',

    // Delivery
    'faq.del.q1.t': '¿Hacen entregas en todo el país?',
    'faq.del.q1.a': 'Sí, ofrecemos servicio de entrega en toda Alemania. Los costes se calculan según la distancia.',
    'faq.del.q2.t': '¿Cuánto tarda la entrega?',
    'faq.del.q2.a': 'Normalmente entre 3 y 7 días laborables tras el pago. Con financiación puede tardar un poco más.',
    'faq.del.q3.t': '¿Puedo recogerlo yo mismo?',
    'faq.del.q3.a': '¡Claro! Puede venir a recogerlo personalmente. Le explicaremos todo sobre el vehículo.',
    'faq.del.q4.t': '¿El coche se entrega matriculado?',
    'faq.del.q4.a': 'Bajo petición, gestionamos el trámite. Si no, puede venir con placas temporales.',

    // Documents
    'faq.doc.q1.t': '¿Qué documentos recibo al comprar?',
    'faq.doc.q1.a': 'Recibe: Título de propiedad, permiso de circulación, contrato, papeles COC, libro de revisiones e ITV.',
    'faq.doc.q2.t': '¿Tiene libro de mantenimiento?',
    'faq.doc.q2.a': 'La mayoría de nuestros coches lo tienen. Si no, solemos poder trazar el historial vía talleres oficiales.',
    'faq.doc.q3.t': '¿Me dan factura?',
    'faq.doc.q3.a': 'Sí, recibirá una factura formal por su compra. Es necesaria para el registro.',
    'faq.doc.q4.t': '¿Y si falta algún documento?',
    'faq.doc.q4.a': 'Solemos poder solicitar duplicados. Puede tardar unas semanas y tener costes adicionales.',

    // Story
    'story.hero.badge': 'Excelencia y Confianza',
    'story.hero.title1': 'Nuestra',
    'story.hero.title2': 'Filosofía',
    'story.hero.subtitle': 'Pasión, confianza y calidad. Descubra los principios que definen a Nordhessen Automobile.',
    
    'story.phil.badge': 'Por Qué Confiar En Nosotros',
    'story.phil.title1': 'Su Socio Automotriz',
    'story.phil.title2': 'de Confianza',
    'story.phil.subtitle': 'Hemos construido nuestra reputación sobre una base de transparencia absoluta, riguroso control de calidad y estándares intransigentes. Descubra por qué los clientes confían en nosotros.',
    'story.phil.1.title': 'Inspección de Calidad de 150 Puntos',
    'story.phil.1.desc': 'Cada vehículo debe someterse a una rigurosa inspección técnica de 150 puntos por mecánicos certificados antes de ingresar a nuestra sala de exposición.',
    'story.phil.1.link': 'Calidad Certificada',
    'story.phil.2.title': 'Transparencia Absoluta',
    'story.phil.2.desc': 'Proporcionamos historiales completos, kilometraje verificable y registros de servicio detallados para cada automóvil. Sin tarifas ocultas.',
    'story.phil.2.link': 'Historial Verificado',
    'story.phil.3.title': 'Garantías Premium',
    'story.phil.3.desc': 'Su tranquilidad está garantizada. Ofrecemos paquetes de garantía integrales, asegurando que esté protegido mucho después de su compra.',
    'story.phil.3.link': 'Protección Garantizada',
    'story.phil.4.title': 'Proceso Seguro y Sencillo',
    'story.phil.4.desc': 'Desde opciones de financiamiento seguras hasta valoraciones de intercambio, nuestro proceso está diseñado para ser totalmente legal, seguro y sin estrés.',
    'story.phil.4.link': 'Compra Sin Riesgos',
    'story.phil.quote': 'La confianza no se otorga, se gana mediante una calidad constante, transparencia y un compromiso con la excelencia.',

    'story.values.badge': 'Valores',
    'story.values.title': 'Lo que nos mueve',
    'story.values.subtitle': 'Estos cuatro pilares forman la base de nuestro trabajo diario.',
    'story.values.1.title': 'Confianza',
    'story.values.1.desc': 'Transparencia absoluta en cada coche y precio. Sin sorpresas, solo asesoramiento honesto.',
    'story.values.2.title': 'Qualidad',
    'story.values.2.desc': 'Solo coches que cumplen nuestros estándares. Cada vehículo se prepara con el máximo cuidado.',
    'story.values.3.title': 'Atención al cliente',
    'story.values.3.desc': 'Asesoramiento personal. Nos tomamos el tiempo necesario para sus deseos individuales.',
    'story.values.4.title': 'Innovadora',
    'story.values.4.desc': 'Tecnología moderna y servicio humano. Procesos digitales para su comodidad, pericia humana para su seguridad.',

    'story.badges.1.label': 'Clientes satisfechos',
