    'legal.impressum.status': 'Estado: Marzo 2026',
    'legal.impressum.source': 'Fuente: eRecht24',

    'legal.privacy.title': 'Política de Privacidad',

    // Geschichte / Story page
    'story.hero.badge': 'Desde 2014',
    'story.hero.title.prefix': 'Nuestra',
    'story.hero.title.highlight': 'Historia',
    'story.hero.subtitle': 'Desde su fundación el 18.07.2014 por Yves Seidler y Dimitri, Nordhessen Automobile ha evolucionado de forma constante: del comercio europeo de vehículos de ocasión a un concesionario moderno con taller propio y una amplia oferta de servicios.',
    'story.vision.title': 'Nuestra Visión',
    'story.vision.desc': 'Queremos conectar personas, vehículos y servicio al más alto nivel. Nuestro objetivo es ser reconocidos en toda Europa como un socio fiable para vehículos de calidad, servicios modernos de taller y atención personalizada. La confianza, la calidad y las relaciones duraderas con los clientes son el centro de todo lo que hacemos.',
    'story.mission.title': 'Nuestra Misión',
    'story.mission.desc': 'Ofrecemos a nuestros clientes un concepto integral de movilidad: desde la compra del vehículo, la financiación y la exportación, hasta los servicios profesionales de taller. Con pasión por el automóvil, procesos modernos y un equipo sólido, creamos soluciones personalizadas, transparentes y fiables. Nuestra ambición es atender a cada cliente como nos gustaría ser atendidos.',
    'story.timeline.badge': 'Historia',
    'story.timeline.title': 'Nuestros Hitos',
    'story.timeline.2014.title': 'El Inicio',
    'story.timeline.2014.desc': 'Fundación el 18.07.2014: inicio de la venta de vehículos de ocasión a nivel europeo. La confianza, la calidad y la satisfacción del cliente son, desde entonces, la base de nuestra empresa.',
    'story.timeline.2015.title': 'Taller Propio',
    'story.timeline.2015.desc': 'Creación del taller propio para reparaciones y preparación de vehículos, garantizando altos estándares de calidad.',
    'story.timeline.2016.title': 'Crecimiento y Logística',
    'story.timeline.2016.desc': 'Ampliación del equipo en gestión y logística de vehículos para asegurar procesos profesionales.',
    'story.timeline.2019_20.title': 'Ampliación del Equipo',
    'story.timeline.2019_20.desc': 'Refuerzo de las áreas de gestión de flota, ventas y contabilidad.',
    'story.timeline.2021.title': 'Formación y Futuro',
    'story.timeline.2021.desc': 'Incorporación del primer aprendiz como técnico comercial en automoción: un paso importante para formar a la próxima generación.',
    'story.timeline.2023.title': 'Ampliación Sandershäuser Straße',
    'story.timeline.2023.desc': 'Ampliación con otro edificio en Sandershäuser Straße 89, con más oficinas y zonas de exposición interiores y exteriores.',
    'story.timeline.2024.title': 'Nuevo Taller Moderno',
    'story.timeline.2024.desc': 'Traslado a un taller de unos 700 m² con cinco puestos de trabajo totalmente equipados.',
    'story.timeline.2025.title': 'Refuerzo del Equipo de Ventas',
    'story.timeline.2025.desc': 'Ampliación del equipo comercial con más colaboradores para responder a la elevada demanda.',
    'story.timeline.2026.title': 'Nordhessen Service GmbH',
    'story.timeline.2026.desc': 'Constitución de Nordhessen Service GmbH como taller maestro de reparación automotriz para clientes particulares y empresariales.',
    'story.values.badge': 'Nuestros Valores',
    'story.values.title': 'Lo que defendemos',
    'story.values.trust.title': 'Confianza y Transparencia',
    'story.values.trust.desc': 'Asesoramos de forma honesta, justa y clara. Queremos que nuestros clientes se sientan seguros y bien atendidos en cada paso.',
    'story.values.service.title': 'Orientación al Servicio',
    'story.values.service.desc': 'La satisfacción del cliente es nuestra prioridad. Ofrecemos soluciones individuales y acompañamos a nuestros clientes a largo plazo.',
    'story.values.quality.title': 'Calidad y Fiabilidad',
    'story.values.quality.desc': 'Venta de vehículos de primera categoría, servicio profesional de taller y un servicio completo de 360 grados para su movilidad.',
    'story.values.passion.title': 'Pasión por los Automóviles',
    'story.values.passion.desc': 'Para nosotros, los coches son mucho más que vehículos: representan movilidad, emoción y confianza.',
    'story.values.assurance.title': 'Aseguramiento de la Calidad',
    'story.values.assurance.desc': 'Cada vehículo se revisa cuidadosamente en el taller y se prepara de forma profesional antes de ser entregado al cliente.',
    'story.values.team.title': 'Espíritu de Equipo',
    'story.values.team.desc': 'Nuestro éxito se basa en un equipo fuerte y motivado que crece junto y se apoya mutuamente.',
    'story.today.title.prefix': 'Nordhessen Automobile',
    'story.today.title.highlight': 'hoy',
    'story.today.desc': 'Hoy, Nordhessen Automobile representa vehículos de ocasión de alta calidad, servicios profesionales de taller, comercio automovilístico a nivel europeo y atención personalizada al cliente. Como concesionario moderno y taller en Kassel y la región de Hesse del Norte, evolucionamos de forma continua, siempre con el objetivo de ofrecer a nuestros clientes el mejor servicio posible en todo lo relacionado con el automóvil.',
    'story.today.tag.1': 'Vehículos de ocasión de alta calidad',
    'story.today.tag.2': 'Taller automovilístico profesional',
    'story.today.tag.3': 'Comercio automovilístico europeo',
    'story.today.tag.4': 'Atención personalizada al cliente',
    'story.today.tag.5': 'Logística automovilística moderna',
    'story.today.tag.6': 'Calidad y Confianza',
    'story.cta.title.prefix': '¿Listo para su',
    'story.cta.title.highlight': 'coche soñado?',
    'story.cta.subtitle': 'Descubra nuestra selección actual de vehículos o contáctenos para un asesoramiento personalizado.',
    'story.cta.browse': 'Descubrir vehículos',
    'story.cta.contact': 'Contactar',
