const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

const isValidLanguage = (lang: string | null): lang is Language => {
  return ['de', 'en', 'pt', 'fr', 'es', 'it'].includes(lang as string);
};

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem('site_language');
    return isValidLanguage(saved) ? saved : 'de';
  });

  useEffect(() => {
    localStorage.setItem('site_language', language);
    document.documentElement.lang = language;
  }, [language]);

  const t = (key: string, args?: Record<string, string | number>) => {
    let text = translations[language][key];
    
    // Fallback for attr.* keys: return the value part instead of the key
    if (text === undefined && key.startsWith('attr.')) {
      // Return the last part of the key (the actual value)
      const parts = key.split('.');
      text = parts[parts.length - 1];
    }
    
    // Final fallback: return key itself
    if (text === undefined) text = key;
    
    if (args) {
      Object.entries(args).forEach(([k, v]) => {
        text = text.replace(`{${k}}`, v.toString());
      });
    }
    return text;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}
